import "@mui/material/Tabs";
import { NextChevronRightArrow, PreviousChevronLeftArrow } from "@rapid7/icons";
export const ThemedTabs = {
    defaultProps: {
        slots: {
            EndScrollButtonIcon: NextChevronRightArrow,
            StartScrollButtonIcon: PreviousChevronLeftArrow,
        },
    },
    styleOverrides: {
        indicator: ({ theme, ownerState }) => ({
            borderRadius: theme.shape.borderRadius,
            height: 3,
            width: 3,
            ...(ownerState.orientation === "vertical" && {
                left: 0,
                right: "auto",
            }),
        }),
        root: ({ ownerState }) => ({
            "&:has(.Mui-selected.Mui-focusVisible) .MuiTabs-indicator": {
                transition: "none",
                ...(ownerState.orientation === "vertical"
                    ? { left: 3 }
                    : { bottom: 3 }),
            },
            ...(ownerState.orientation === "vertical" && {
                minWidth: 120,
            }),
        }),
        scroller: ({ theme, ownerState }) => ({
            backgroundImage: `linear-gradient(to top, transparent 1px, ${theme.palette.divider} 1px, ${theme.palette.divider} 2px, transparent 2px)`,
            ...(ownerState.orientation === "vertical" && {
                backgroundImage: "none",
            }),
        }),
    },
};
